import globimport oslog_directory = r'C:\Users\Dominik\sciebo\Uni\VW_Scenarios\scenarios_all'video_directory = r'D:\github\aqua\stars-export-carla\videos'if __name__ == '__main__':    log_files = []    for root, dirs, files in os.walk(log_directory):        for file in glob.glob(os.path.join(root, '*.log')):            log_files.append(file.split('\\')[-2] + "\\" + file.split('\\')[-1].split('.')[0])    video_files = []    for file in glob.glob(os.path.join(video_directory, '*.mp4')):        video_files.append(file.split('\\')[-1].split('-')[0])    missing = []    for file in log_files:        if file.split('\\')[1] not in video_files:            missing.append(file.split('\\')[0])    print("========================================")    print(f"Missing videos: {len(missing)}")    print("========================================")    for file in missing:        print(file)